import { Component, ErrorInfo, ReactNode, useEffect, useMemo, useRef, useState } from 'react';
import { Activity, AlertTriangle, Box, Braces, CheckCircle2, Copy, Plug, ShieldCheck, ChevronRight, Database, History, LayoutDashboard, Loader2, Menu, Plus, Search, Settings as SettingsIcon, Sparkles, Terminal, Bot, Zap, LogOut, Circle, Trash2, RefreshCw, ExternalLink, Maximize2, Monitor, Smartphone, Tablet, Globe2, Server } from 'lucide-react';
import { builderStages, stageState } from './builderStages';
import { classifyBuildStatus, isBuildTerminal, latestBuild, type WorkspaceBuildStatus } from './workspaceLifecycle';
type Page = 'Overview'|'Projects'|'Workspace'|'Database'|'API explorer'|'Logs'|'AI builder'|'Versions'|'Deployments'|'Settings'|'MCP Connections';
type Project = { id:string; name:string; environment:string; previewUrl:string; productionUrl?:string; publicClientId?:string };
const pages: Page[] = ['Overview','Projects','Workspace','Database','API explorer','Logs','Versions','Deployments','Settings'];
const navigationGroups: { label: string; items: Page[] }[] = [{ label: 'Build', items: ['Overview','Projects','Workspace','Database','API explorer'] }, { label: 'Ship', items: ['Versions','Deployments'] }, { label: 'Observe', items: ['Logs','Settings'] }];
const pageIcons: Record<Page, any> = { Overview: LayoutDashboard, Projects: Box, Workspace: Monitor, Database, 'API explorer': Braces, Logs: Terminal, 'AI builder': Bot, Versions: History, Deployments: Globe2, Settings: SettingsIcon, 'MCP Connections': Plug };
const api = (import.meta.env.VITE_API_URL as string|undefined)?.replace(/\/$/, '') || 'http://localhost:3000/api'; const v1 = `${api}/v1`;
type StructuredError = Error & { code?:string; stage?:string; requestId?:string; diagnostics?:any[]; stages?:any[]; provider?:string; model?:string; retryAfter?:number|string; nextRetryAt?:number|string; response?:any };
async function request(path:string, options:RequestInit={}) { let r:Response; try { r=await fetch(`${v1}${path}`,{...options,credentials:'include',headers:{'content-type':'application/json',...(options.headers||{})}}); } catch (cause) { const message=cause instanceof Error?cause.message:'Network request failed'; throw Object.assign(new Error(`Could not reach AppWeave API. Check your connection and API status, then try again. (${message})`),{code:'NETWORK_ERROR',cause}); } const body=await r.json().catch(()=>({})); if(!r.ok) { const detail=body.error||body; const requestId=detail.requestId||body.requestId; const error=Object.assign(new Error(`${detail.message||body.message||'Request failed'}${requestId?` (request ${requestId})`:''}`),{code:detail.code,stage:detail.stage,requestId,diagnostics:detail.diagnostics||body.diagnostics||[],stages:detail.stages||body.stages||[],provider:detail.provider||body.provider,model:detail.model,retryAfter:detail.retryAfter??detail.retry_after??body.retryAfter??body.retry_after,nextRetryAt:detail.nextRetryAt??detail.next_retry_at??body.nextRetryAt??body.nextRetryAt,response:body}); throw error as StructuredError; } return body; }
class ErrorBoundary extends Component<{children:ReactNode},{error:Error|null}> { state={error:null as Error|null}; static getDerivedStateFromError(error:Error){return {error};} componentDidCatch(error:Error,info:ErrorInfo){console.error('AppWeave page rendering failed',error,info);} render(){return this.state.error?<main><section className="panel empty tall"><AlertTriangle size={28}/><b>This page could not be displayed</b><p>{this.state.error.message||'Unexpected rendering error.'}</p><Button primary onClick={()=>this.setState({error:null})}>Try again</Button></section></main>:this.props.children;} }

function Button({children,primary,onClick,type='button',disabled=false}:any){return <button disabled={disabled} type={type} className={primary?'btn primary':'btn'} onClick={onClick}>{children}</button>}
function Header({eyebrow,title,actions}:any){return <header className="head"><div><small className="eyebrow">{eyebrow}</small><h1>{title}</h1></div><div className="actions">{actions}</div></header>}
function Notice({children,error=false,success=false}:any){return <div className={success?'notice success':error?'unavailable error':'unavailable'}>{success?<CheckCircle2 size={16}/>:<AlertTriangle size={16}/>}<div>{children}</div></div>}
function ProjectBar({projects=[],selectedId='',onSelect=()=>{}}:any){return <div className="projectbar"><Box size={15}/><span>Project</span><select value={selectedId} onChange={e=>onSelect(e.target.value)} aria-label="Selected project"><option value="">Select a project</option>{projects.map((p:Project)=><option key={p.id} value={p.id}>{p.name}</option>)}</select>{selectedId&&<em>active</em>}</div>}
function ApiStatus(){const [state,setState]=useState<'checking'|'online'|'offline'>('checking');useEffect(()=>{let alive=true;const ping=()=>fetch(`${api.replace(/\/api$/,'')}/health`,{credentials:'include'}).then(r=>{if(!r.ok)throw Error();if(alive)setState('online')}).catch(()=>alive&&setState('offline'));ping();const timer=window.setInterval(ping,30000);return()=>{alive=false;window.clearInterval(timer)}},[]);return <div className={`api-status ${state}`}><Circle size={8} fill="currentColor"/> API {state==='checking'?'checking…':state==='online'?'connected':'offline'}</div>}
function Overview({go,project}:any){const [data,setData]=useState<any>();const [error,setError]=useState('');useEffect(()=>{request('/overview').then(setData).catch(e=>setError(e.message))},[]);return <><Header eyebrow="Workspace overview" title="Build, test, and ship from one workspace." actions={<Button primary onClick={()=>go('Projects')}><Plus size={14}/> New project</Button>}/><main><ProjectBar {...project}/><div className="hero"><div><small className="eyebrow orange"><Sparkles size={13}/> Managed application platform</small><h2>Your command center for production apps.</h2><p>Define your data, review AI changes, launch a preview, and publish safely.</p></div><div className="glow"><Zap size={28}/></div></div>{error&&<Notice error>{error}</Notice>}<div className="stats">{[['Active projects','activeProjects'],['API requests','requests'],['Deployments','deployments'],['Records','databaseRecords']].map(([label,key])=><div className="stat" key={key}><span>{label}<Activity size={15}/></span><b>{data?.[key]??'—'}</b><small>Live backend metric</small></div>)}</div><div className="cols"><section className="panel"><small className="eyebrow">Get started</small><h3>Build your first application</h3>{[['01','Create a project'],['02','Shape your data'],['03','Preview and publish']].map(x=><div className="step" key={x[0]}><i>{x[0]}</i><div><b>{x[1]}</b><p>Use the managed backend and review every change.</p></div><ChevronRight size={15}/></div>)}<Button primary onClick={()=>go('Projects')}><Plus size={14}/> Create project</Button></section><section className="panel"><small className="eyebrow">Operational truth</small><h3>Workspace pulse</h3><div className="empty"><Activity size={24}/><b>Metrics are live</b><p>Requests, records, deployments, and audit events are read from your backend.</p></div></section></div></main></>}
  function Projects({go,projects,selectedId,onSelect,reload}:any){const [name,setName]=useState('');const [error,setError]=useState('');const [success,setSuccess]=useState('');const [loading,setLoading]=useState(false);async function create(e:any){e.preventDefault();setError('');setSuccess('');if(!name.trim()){setError('Project name is required.');return}setLoading(true);try{const created=await request('/projects',{method:'POST',body:JSON.stringify({name:name.trim()})});setName('');onSelect(created.id);setSuccess('Project created and selected.');await reload();go('Workspace')}catch(e:any){setError(e.message)}finally{setLoading(false)}}return <><Header eyebrow="Workspace / Projects" title="Projects"/><main><form className="toolbar" onSubmit={create}><div className="search"><Search size={15}/><input value={name} onChange={e=>setName(e.target.value)} placeholder="Project name" aria-label="Project name"/></div><Button primary type="submit" disabled={loading}>{loading&&<Loader2 className="spin" size={14}/>}<Plus size={14}/> {loading?'Creating…':'Create project'}</Button></form>{error&&<Notice error>{error}</Notice>}{success&&<Notice success>{success}</Notice>}<div className="project-grid">{projects.map((p:Project)=><div className={`project ${p.id===selectedId?'selected-project':''}`} key={p.id}><Box size={19}/><h3>{p.name}</h3><p>{p.environment} · {p.id.slice(0,8)}</p><div className="project-actions"><Button primary onClick={()=>{onSelect(p.id);go('Workspace')}}><Monitor size={13}/> Open workspace</Button><a className="preview-link" href={p.previewUrl} target="_blank" rel="noreferrer">Preview in new tab <ExternalLink size={13}/></a></div></div>)}{!projects.length&&<div className="tile"><div className="plus">+</div><h3>Create your first project</h3><p>Projects own isolated data, API definitions, environments, and versions.</p></div>}</div></main></>}
function Workspace({project,projects,onSelect}:any){
  const [tab,setTab]=useState<'preview'|'services'>('preview');
  const [device,setDevice]=useState('responsive');
  const [refreshKey,setRefreshKey]=useState(0);
  const [frameState,setFrameState]=useState<'loading'|'ready'|'error'>('loading');
  const [builds,setBuilds]=useState<any[]>([]);
  const [buildStatus,setBuildStatus]=useState<WorkspaceBuildStatus>('unavailable');
  const [error,setError]=useState<any>();
  const [building,setBuilding]=useState(false);
  const [publishing,setPublishing]=useState(false);
  const [productionUrl,setProductionUrl]=useState(project?.productionUrl||'');
  const frameRef=useRef<HTMLDivElement>(null);
  const previewUrl=project?.previewUrl||'';
  const latestPreview=latestBuild(builds,'preview');
  const diagnostics=latestPreview?.diagnostics||latestPreview?.buildLog||latestPreview?.stages||error?.diagnostics||[];
  const statusLabel={initializing:'Initializing',building:'Building',ready:'Ready',failed:'Failed',unavailable:'Unavailable'}[buildStatus];
  const apiOffline=error?.code==='NETWORK_ERROR';
  const statusMessage={initializing:'Preparing a build for this workspace…',building:'Build is in progress. This preview updates automatically.',ready:'Preview is ready to inspect.',failed:'The latest build failed. Review diagnostics and try again.',unavailable:apiOffline?'The AppWeave API is offline. Check the API status and try again.':'No preview build is available yet.'}[buildStatus];
  async function loadBuilds(){
    if(!project){setBuilds([]);setBuildStatus('unavailable');return []}
    try{
      const response=await request(`/projects/${project.id}/builds`); const items=response.builds||[]; setBuilds(items);
      const latest=latestBuild(items,'preview'); setBuildStatus(classifyBuildStatus(latest,!!previewUrl));
      return items;
    }catch(e:any){setError(e);setBuildStatus('unavailable');return []}
  }
  useEffect(()=>{setError(undefined);setFrameState(previewUrl?'loading':'error');setProductionUrl(project?.productionUrl||'');loadBuilds()},[project?.id,previewUrl]);
  useEffect(()=>{if(!project||!latestPreview||isBuildTerminal(latestPreview))return;const timer=window.setInterval(loadBuilds,2000);return()=>window.clearInterval(timer)},[project?.id,latestPreview?.id,latestPreview?.status]);
  useEffect(()=>{if(frameState!=='loading')return;const configured=Number(import.meta.env.VITE_PREVIEW_TIMEOUT_MS);const timeout=Number.isFinite(configured)&&configured>=1000?configured:10000;const timer=window.setTimeout(()=>setFrameState('error'),timeout);return()=>clearTimeout(timer)},[frameState,refreshKey]);
  async function buildPreview(){
    if(!project||building)return; setBuilding(true);setError(undefined);setBuildStatus('initializing');
    try{if(!latestPreview?.version){setError(new Error('Build preview requires a validated application specification.'));setBuildStatus('unavailable');return}const result=await request(`/projects/${project.id}/builds`,{method:'POST',body:JSON.stringify({environment:'preview',version:latestPreview.version})});setBuilds(items=>[result,...items.filter(item=>item.id!==result.id)]);setBuildStatus(classifyBuildStatus(result,!!result.url));setFrameState('loading');setRefreshKey(key=>key+1)}catch(e:any){setError(e);setBuildStatus('failed')}finally{setBuilding(false)}
  }
  async function publish(){
    if(!project||publishing)return; setPublishing(true);setError(undefined);
    try{if(!latestPreview?.version){setError(new Error('Publish requires a validated preview build first.'));return}const result=await request(`/projects/${project.id}/publish`,{method:'POST',body:JSON.stringify({version:latestPreview.version})});setProductionUrl(result.url||`${api.replace(/\/api$/,'')}/app/${project.id}`);setBuilds(items=>[result,...items.filter(item=>item.id!==result.id)])}catch(e:any){setError(e);setBuildStatus('failed')}finally{setPublishing(false)}
  }
  function retryPreview(){setRefreshKey(key=>key+1);setFrameState('loading');loadBuilds()}
  function openProduction(){if(productionUrl)window.open(productionUrl,'_blank','noopener,noreferrer')}
  function openPreview(){if(previewUrl)window.open(previewUrl,'_blank','noopener,noreferrer')}
  function fullscreen(){const node=frameRef.current;if(node?.requestFullscreen)node.requestFullscreen()}
  const deviceClass=device==='responsive'?'device-responsive':`device-${device}`;
  const canPublish=!!project&&buildStatus==='ready'&&!!latestPreview&&!publishing;
  return <><Header eyebrow="Workspace / Preview" title={project?.name||'Project workspace'} actions={<>{productionUrl&&<Button onClick={openProduction}><ExternalLink size={13}/> Open production</Button>}<Button primary disabled={!canPublish} onClick={publish}>{publishing&&<Loader2 className="spin" size={13}/>} Publish</Button></>}/><main className="workspace-page"><ProjectBar projects={projects} selectedId={project?.id||''} onSelect={onSelect}/>{!project?<section className="panel empty tall"><Monitor size={28}/><b>Select a project to open its workspace</b><p>Choose a project to inspect its real backend preview.</p></section>:<section className="workspace-shell"><div className="workspace-toolbar"><div className="workspace-tabs"><button className={tab==='preview'?'active':''} onClick={()=>setTab('preview')}><Monitor size={14}/> Preview</button><button className={tab==='services'?'active':''} onClick={()=>setTab('services')}><Server size={14}/> Services</button></div><div className="workspace-controls">{tab==='preview'&&<><label className="route-field"><Globe2 size={13}/><input value={previewUrl} readOnly aria-label="Preview route"/></label><span className={`preview-status ${buildStatus}`}><Circle size={7} fill="currentColor"/>{statusLabel}</span><Button primary onClick={buildPreview} disabled={building||publishing}>{building&&<Loader2 className="spin" size={13}/>} {building?'Building preview':'Build preview'}</Button><Button onClick={retryPreview} disabled={!previewUrl||building}><RefreshCw size={13}/> Refresh</Button><Button onClick={fullscreen} disabled={frameState!=='ready'}><Maximize2 size={13}/> Fullscreen</Button><Button onClick={openPreview} disabled={!previewUrl}><ExternalLink size={13}/> Open new tab</Button></>}</div></div>{error&&<Notice error><strong>{error.message||'Workspace request failed'}</strong>{error.requestId&&<small>Request ID: {error.requestId}</small>}</Notice>}{(buildStatus==='initializing'||buildStatus==='building'||buildStatus==='failed'||buildStatus==='unavailable')&&<div className={`workspace-build-status ${buildStatus}`} role="status"><b>{statusLabel}</b><span>{statusMessage}</span></div>}{diagnostics.length>0&&<section className="workspace-diagnostics"><div><small className="eyebrow">Build diagnostics</small><b>Latest preview pipeline</b></div>{diagnostics.map((item:any,index:number)=><div className="diagnostic" key={index}><span>{item.name||item.stage||item.path||'Build'}</span><p>{item.message||item.detail||item.status||String(item)}</p></div>)}</section>}{tab==='services'?<div className="services-grid"><div className="service-card"><Server size={17}/><div><b>Managed API</b><p>{v1}</p></div><span className="service-live">Connected</span></div><div className="service-card"><Globe2 size={17}/><div><b>Preview route</b><p>{previewUrl||'No preview route is available.'}</p></div></div><div className="service-card"><ShieldCheck size={17}/><div><b>Public client</b><p>{project.publicClientId||'Not configured'}</p></div></div><div className="service-card"><History size={17}/><div><b>Deployments</b><p>{builds.length?`${builds.length} build${builds.length===1?'':'s'} recorded`:'No builds yet'}</p></div></div></div>:<div ref={frameRef} className={`preview-stage ${deviceClass}`}>{!previewUrl?<div className="preview-empty"><Monitor size={28}/><b>No preview URL available</b><p>Build a preview to create a route for this project.</p><Button primary onClick={buildPreview} disabled={building}>Build preview</Button></div>:buildStatus==='failed'?<div className="preview-empty"><AlertTriangle size={28}/><b>Preview build failed</b><p>Review the diagnostics above, then build the preview again.</p><Button onClick={buildPreview} disabled={building}><RefreshCw size={13}/> Try build again</Button></div>:<><div className="preview-device-bar"><span>Preview</span><div className="device-modes"><button className={device==='desktop'?'active':''} onClick={()=>setDevice('desktop')}><Monitor size={13}/> Desktop</button><button className={device==='iphone'?'active':''} onClick={()=>setDevice('iphone')}><Smartphone size={13}/> iPhone <small>393×852</small></button><button className={device==='pixel'?'active':''} onClick={()=>setDevice('pixel')}><Smartphone size={13}/> Pixel <small>412×915</small></button><button className={device==='ipad'?'active':''} onClick={()=>setDevice('ipad')}><Tablet size={13}/> iPad <small>820×1180</small></button><button className={device==='responsive'?'active':''} onClick={()=>setDevice('responsive')}><Globe2 size={13}/> Responsive</button></div></div>{frameState==='loading'&&<div className="preview-loading"><Loader2 className="spin" size={18}/> Loading real preview…</div>}<iframe key={refreshKey} src={previewUrl} title={`${project.name} preview`} className="preview-frame" onLoad={()=>setFrameState('ready')} onError={()=>setFrameState('error')} /></>}</div>}</section>}</main></>}

function LegacyWorkspace({project,projects,onSelect}:any){const [tab,setTab]=useState<'preview'|'services'>('preview');const [device,setDevice]=useState('responsive');const [refreshKey,setRefreshKey]=useState(0);const [frameState,setFrameState]=useState<'loading'|'ready'|'error'>('loading');const [builds,setBuilds]=useState<any[]>([]);const [error,setError]=useState('');const [publishing,setPublishing]=useState(false);const [productionUrl,setProductionUrl]=useState(project?.productionUrl||'');const frameRef=useState<React.RefObject<HTMLDivElement>>(()=>({current:null}))[0];const previewUrl=project?.previewUrl||'';const latestPreview=builds.filter(x=>x.environment==='preview').sort((a,b)=>b.version-a.version)[0];useEffect(()=>{setFrameState(previewUrl?'loading':'error');setProductionUrl(project?.productionUrl||'');if(!project){setBuilds([]);return}request(`/projects/${project.id}/builds`).then(x=>setBuilds(x.builds||[])).catch(e=>setError(e.message))},[project?.id,previewUrl]);useEffect(()=>{if(frameState!=='loading')return;const timer=window.setTimeout(()=>setFrameState('error'),10000);return()=>window.clearTimeout(timer)},[frameState,refreshKey]);async function publish(){if(!project)return;setPublishing(true);setError('');try{const result=await request(`/projects/${project.id}/publish`,{method:'POST',body:JSON.stringify({version:latestPreview?.version||1})});setProductionUrl(result.url||`${api.replace(/\/api$/,'')}/app/${project.id}`);setBuilds(items=>[...items,result])}catch(e:any){setError(e.message)}finally{setPublishing(false)}}function openProduction(){if(productionUrl)window.open(productionUrl,'_blank','noopener,noreferrer')}function openPreview(){if(previewUrl)window.open(previewUrl,'_blank','noopener,noreferrer')}function fullscreen(){const node=frameRef.current;if(node?.requestFullscreen)node.requestFullscreen()}const deviceClass=device==='responsive'?'device-responsive':`device-${device}`;return <><Header eyebrow="Workspace / Preview" title={project?.name||'Project workspace'} actions={<>{productionUrl&&<Button onClick={openProduction}><ExternalLink size={13}/> Open production</Button>}<Button primary disabled={!project||publishing} onClick={publish}>{publishing&&<Loader2 className="spin" size={13}/>} Publish</Button></>}/><main className="workspace-page"><ProjectBar projects={projects} selectedId={project?.id||''} onSelect={onSelect}/>{!project?<section className="panel empty tall"><Monitor size={28}/><b>Select a project to open its workspace</b><p>Choose a project to inspect its real backend preview.</p></section>:<section className="workspace-shell"><div className="workspace-toolbar"><div className="workspace-tabs"><button className={tab==='preview'?'active':''} onClick={()=>setTab('preview')}><Monitor size={14}/> Preview</button><button className={tab==='services'?'active':''} onClick={()=>setTab('services')}><Server size={14}/> Services</button></div><div className="workspace-controls">{tab==='preview'&&<><label className="route-field"><Globe2 size={13}/><input value={previewUrl} readOnly aria-label="Preview route"/></label><span className={`preview-status ${frameState}`}><Circle size={7} fill="currentColor"/>{frameState==='loading'?'Loading preview':frameState==='ready'?'Preview ready':'Preview unavailable'}</span><Button onClick={()=>{setRefreshKey(x=>x+1);setFrameState('loading')}} disabled={!previewUrl}><RefreshCw size={13}/> Refresh</Button><Button onClick={fullscreen} disabled={frameState!=='ready'}><Maximize2 size={13}/> Fullscreen</Button><Button onClick={openPreview} disabled={!previewUrl}><ExternalLink size={13}/> Open new tab</Button></>}</div></div>{error&&<Notice error>{error}</Notice>}{tab==='services'?<div className="services-grid"><div className="service-card"><Server size={17}/><div><b>Managed API</b><p>{v1}</p></div><span className="service-live">Connected</span></div><div className="service-card"><Globe2 size={17}/><div><b>Preview route</b><p>{previewUrl||'No preview route is available.'}</p></div></div><div className="service-card"><ShieldCheck size={17}/><div><b>Public client</b><p>{project.publicClientId||'Not configured'}</p></div></div><div className="service-card"><History size={17}/><div><b>Deployments</b><p>{builds.length?`${builds.length} build${builds.length===1?'':'s'} recorded`:'No builds yet'}</p></div></div></div>:<div ref={frameRef} className={`preview-stage ${deviceClass}`}>{!previewUrl?<div className="preview-empty"><Monitor size={28}/><b>No preview URL available</b><p>Build a preview to create a route for this project.</p></div>:frameState==='error'?<div className="preview-empty"><AlertTriangle size={28}/><b>Preview could not be loaded</b><p>Check the API status, then refresh or open the route in a new tab.</p><Button onClick={()=>{setRefreshKey(x=>x+1);setFrameState('loading')}}><RefreshCw size={13}/> Try again</Button></div>:<><div className="preview-device-bar"><span>Preview</span><div className="device-modes"><button className={device==='desktop'?'active':''} onClick={()=>setDevice('desktop')}><Monitor size={13}/> Desktop</button><button className={device==='iphone'?'active':''} onClick={()=>setDevice('iphone')}><Smartphone size={13}/> iPhone <small>393×852</small></button><button className={device==='pixel'?'active':''} onClick={()=>setDevice('pixel')}><Smartphone size={13}/> Pixel <small>412×915</small></button><button className={device==='ipad'?'active':''} onClick={()=>setDevice('ipad')}><Tablet size={13}/> iPad <small>820×1180</small></button><button className={device==='responsive'?'active':''} onClick={()=>setDevice('responsive')}><Globe2 size={13}/> Responsive</button></div></div>{frameState==='loading'&&<div className="preview-loading"><Loader2 className="spin" size={18}/> Loading real preview…</div>}<iframe key={refreshKey} src={previewUrl} title={`${project.name} preview`} className="preview-frame" onLoad={()=>setFrameState('ready')} onError={()=>setFrameState('error')} /></>}</div>}</section>}</main></>}
function DatabasePage({project,projects,onSelect}:any){const [schema,setSchema]=useState<any>();const [products,setProducts]=useState<any[]>([]);const [error,setError]=useState('');useEffect(()=>{if(!project){setSchema(undefined);setProducts([]);return}Promise.all([request(`/projects/${project.id}/schema`),request(`/projects/${project.id}/products`)]).then(([s,p])=>{setSchema(s);setProducts(p.products)}).catch(e=>setError(e.message))},[project?.id]);return <><Header eyebrow="Build / Database" title="Database"/><main><ProjectBar projects={projects} selectedId={project?.id||''} onSelect={onSelect}/>{!project?<div className="panel empty tall"><Database size={28}/><b>Select a project to view its database</b><p>Project data is isolated and loaded only for the selected project.</p></div>:<>{error&&<Notice error>{error}</Notice>}<div className="cols"><section className="panel"><small className="eyebrow">Entities</small><h3>Your data model</h3><div className="entity"><Database size={15}/><div><b>Product</b><small>name · sku · price · description</small></div></div><div className="meta">Schema version {schema?.version??'—'} · {schema?.migrationStatus??'Loading'}</div></section><section className="panel"><small className="eyebrow">Safe data explorer</small><h3>Products</h3>{products.length?<div>{products.map(p=><div className="step" key={p.id}><div><b>{p.name}</b><p>{p.sku} · ${p.price}</p></div></div>)}</div>:<div className="empty"><Database size={22}/><p>No records yet. CRUD access is project-scoped and authenticated.</p></div>}</section></div></>}</main></>}
function SimplePage({title,eyebrow,icon:Icon,description}:any){return <><Header eyebrow={eyebrow} title={title}/><main><section className="panel"><div className="empty tall"><Icon size={28}/><b>{title} is connected to the managed backend</b><p>{description}</p></div></section></main></>}
