export type MCPTokenMetadata = { id:string; name:string; tokenPrefix:string; createdAt:string; lastUsedAt?:string; revokedAt?:string; status:'active'|'revoked' };
export function mcpClientConfig(endpoint:string, token:string) { return { mcpServers: { appweave: { url:endpoint, headers:{ Authorization:`Bearer ${token}` } } } }; }
export function mcpEndpoint() { return `${api.replace(/\/api$/, '')}/mcp`; }
function Connections(){
  const [tokens,setTokens]=useState<MCPTokenMetadata[]>([]); const [name,setName]=useState(''); const [newToken,setNewToken]=useState(''); const [message,setMessage]=useState<any>(); const [loading,setLoading]=useState(false); const [loadingTokens,setLoadingTokens]=useState(true); const [action,setAction]=useState<'create'|'revoke'|'test'|''>(''); const endpoint=mcpEndpoint();
  const load=()=>{setLoadingTokens(true);return request('/mcp/tokens').then(x=>setTokens(x.tokens||[])).catch(e=>setMessage({error:`Could not load MCP tokens. ${e.message}` })).finally(()=>setLoadingTokens(false))}; useEffect(()=>{load()},[]);
  const copy=async(value:string,label:string)=>{try{await navigator.clipboard.writeText(value);setMessage({success:`${label} copied to clipboard.`})}catch{setMessage({error:`Could not copy ${label.toLowerCase()}. Select and copy it manually.`})}};
  async function create(e:any){e.preventDefault();setLoading(true);setAction('create');setMessage(undefined);try{const x=await request('/mcp/tokens',{method:'POST',body:JSON.stringify({name:name.trim()||'MCP client'})});setName('');setNewToken(x.token);setMessage({success:'Token created. Copy it now; it will not be shown again.'});await load()}catch(e:any){setMessage({error:`Could not create MCP token. ${e.message}`})}finally{setLoading(false);setAction('')}}
  async function revoke(id:string){if(!window.confirm('Revoke this MCP token? Any client using it will lose access immediately.'))return;setLoading(true);setAction('revoke');setMessage(undefined);try{await request(`/mcp/tokens/${id}/revoke`,{method:'POST'});await load();setMessage({success:'Token revoked. Clients using it can no longer connect.'})}catch(e:any){setMessage({error:`Could not revoke MCP token. ${e.message}`})}finally{setLoading(false);setAction('')}}
  async function test(){setLoading(true);setAction('test');setMessage(undefined);try{const x=await request('/mcp/connection-test',{method:'POST'});setMessage(x.connected?{success:x.message||'MCP connection succeeded.'}:{error:`MCP connection test failed. ${x.message||'The server did not accept the connection.'}`})}catch(e:any){setMessage({error:`Could not test the MCP connection. ${e.message}`})}finally{setLoading(false);setAction('')}}
  const snippet=newToken?JSON.stringify(mcpClientConfig(endpoint,newToken),null,2):'';
  return <><div className="connector-toolbar"><div><small className="eyebrow">Account / Settings / Connectors</small><h3>MCP Connections</h3></div><Button onClick={test} disabled={loading}>{action==='test'&&<Loader2 className="spin" size={14}/>}<Plug size={14}/> {action==='test'?'Testing connection…':'Test connection'}</Button></div><div><div className="connector-grid"><section className="panel"><small className="eyebrow"><Plug size={12}/> Connect an MCP client</small><h3>Use AppWeave from your MCP client</h3><p className="settings-copy">Create a scoped connector token for an MCP client. Tokens are stored securely and shown only once after creation.</p>{message?.error&&<Notice error>{message.error}</Notice>}{message?.success&&<Notice success>{message.success}</Notice>}<label>Token name<input value={name} onChange={e=>setName(e.target.value)} placeholder="Claude Desktop" maxLength={80}/></label><Button primary onClick={create} disabled={loading}>{action==='create'&&<Loader2 className="spin" size={14}/>} {action==='create'?'Creating token…':'Create MCP token'}</Button>{newToken&&<div className="token-reveal"><b>New token — copy it now</b><code>{newToken}</code><div className="connector-actions"><Button onClick={()=>copy(newToken,'Token')}><Copy size={13}/> Copy token</Button><Button onClick={()=>copy(snippet,'Configuration')}><Copy size={13}/> Copy config</Button></div><pre>{snippet}</pre><small>For security, this token cannot be recovered after leaving this screen.</small></div>}</section><section className="panel"><small className="eyebrow">Client endpoint</small><h3>Endpoint and configuration</h3><p className="settings-copy">Paste this endpoint into an MCP client that supports streamable HTTP.</p><div className="copy-field"><code>{endpoint}</code><Button onClick={()=>copy(endpoint,'Endpoint')}><Copy size={13}/></Button></div><pre className="config-snippet">{JSON.stringify(mcpClientConfig(endpoint,'YOUR_TOKEN'),null,2)}</pre></section></div><section className="panel token-list"><div className="progress-heading"><div><small className="eyebrow">Access inventory</small><h3>Tokens</h3></div><span className="field-help">{loadingTokens?'Loading tokens…':`${tokens.filter(x=>x.status==='active').length} active`}</span></div>{loadingTokens?<div className="empty short"><Loader2 className="spin" size={22}/><p>Loading MCP tokens…</p></div>:tokens.length?tokens.map(item=><div className="token-row" key={item.id}><div><b>{item.name}</b><small>{item.tokenPrefix}… · created {new Date(item.createdAt).toLocaleDateString()}{item.lastUsedAt?` · last used ${new Date(item.lastUsedAt).toLocaleDateString()}`:''}</small></div><span className={item.status==='active'?'token-active':'token-revoked'}>{item.status}</span>{item.status==='active'&&<Button onClick={()=>revoke(item.id)} disabled={loading}>{action==='revoke'&&<Loader2 className="spin" size={12}/>} Revoke</Button>}</div>):<div className="empty short"><ShieldCheck size={22}/><b>No MCP tokens yet</b><p>Create one when you are ready to connect a client.</p></div>}</section></div></>}
function LegacySettings({project,projects,onSelect}:any){const [tab,setTab]=useState<'project'|'providers'>('project');const [settings,setSettings]=useState<any>({name:'',allowedOrigins:'',usageLimit:100000,lifecycleStatus:'active',environment:'development'});const [provider,setProvider]=useState('gemini');const [form,setForm]=useState<any>(defaults.gemini);const [configured,setConfigured]=useState(false);const [message,setMessage]=useState<any>();const [loading,setLoading]=useState(false);const [freeModels,setFreeModels]=useState<any[]>([]);const [modelsLoading,setModelsLoading]=useState(false);useEffect(()=>{if(!project)return;setMessage(undefined);request(`/projects/${project.id}/settings`).then(x=>setSettings({...x,allowedOrigins:(x.allowedOrigins||[]).join('\n')})).catch(e=>setMessage({error:e.message}));request(`/projects/${project.id}/providers`).then(x=>{const c=x.providers?.find((p:any)=>p.provider===provider);if(c){setForm({baseUrl:c.baseUrl,model:c.model,key:''});setConfigured(c.configured)}}).catch(e=>setMessage({error:e.message}))},[project?.id]);useEffect(()=>{if(!project)return;request(`/projects/${project.id}/providers`).then(x=>{const c=x.providers?.find((p:any)=>p.provider===provider);setForm(c?{baseUrl:c.baseUrl,model:c.model,key:''}:defaults[provider]);setConfigured(!!c?.configured)}).catch(()=>{})},[provider]);async function saveSettings(e:any){e.preventDefault();try{setLoading(true);setMessage(undefined);await request(`/projects/${project.id}/settings`,{method:'PATCH',body:JSON.stringify({...settings,allowedOrigins:settings.allowedOrigins.split('\n').map((x:string)=>x.trim()).filter(Boolean)})});setMessage({success:'Project settings saved.'})}catch(e:any){setMessage({error:e.message})}finally{setLoading(false)}}async function saveProvider(){try{setLoading(true);setMessage(undefined);await request(`/projects/${project.id}/providers/${provider}`,{method:'PATCH',body:JSON.stringify(form)});setConfigured(true);setForm((x:any)=>({...x,key:''}));setMessage({success:`${provider} configuration saved.`})}catch(e:any){setMessage({error:e.message})}finally{setLoading(false)}}async function testProvider(){try{setLoading(true);setMessage(undefined);const result=await request(`/projects/${project.id}/providers/${provider}/test`,{method:'POST',body:JSON.stringify(form)});setMessage(result.reachable?{success:`${provider} · ${form.model} responded successfully.`}:{error:`${provider} · ${form.model}: ${result.message||'Model is not reachable. Check that this model is enabled for your API key.'}`})}catch(e:any){setMessage({error:e.message})}finally{setLoading(false)}}async function loadFreeModels(){if(!project||provider!=='openrouter')return;try{setModelsLoading(true);setMessage(undefined);const result=await request(`/projects/${project.id}/providers/openrouter/models`);setFreeModels(result.models||[]);setMessage({success:`Loaded ${result.models?.length||0} free OpenRouter models.`})}catch(e:any){setMessage({error:e.message})}finally{setModelsLoading(false)}} async function removeProvider(){try{setLoading(true);await request(`/projects/${project.id}/providers/${provider}`,{method:'DELETE'});setConfigured(false);setForm(defaults[provider]);setMessage({success:'Provider removed.'})}catch(e:any){setMessage({error:e.message})}finally{setLoading(false)}}return <><Header eyebrow="Account / Settings" title="Settings"/><main><ProjectBar projects={projects} selectedId={project?.id||''} onSelect={onSelect}/>{!project?<div className="panel empty tall"><SettingsIcon size={28}/><b>Select a project to manage settings</b></div>:<div className="settings"><nav><button className={tab==='project'?'active':''} onClick={()=>setTab('project')}><SettingsIcon size={14}/> Project settings</button><button className={tab==='providers'?'active':''} onClick={()=>setTab('providers')}><Sparkles size={14}/> AI Providers</button><button onClick={()=>window.dispatchEvent(new CustomEvent('appweave:navigate',{detail:'MCP Connections'}))}><Plug size={14}/> MCP Connections</button></nav><section className="panel">{message?.error&&<Notice error>{message.error}</Notice>}{message?.success&&<Notice success>{message.success}</Notice>}{tab==='project'?<form onSubmit={saveSettings}><small className="eyebrow">Project configuration</small><h3>Environment and access</h3><label>Project name<input value={settings.name} onChange={e=>setSettings({...settings,name:e.target.value})}/></label><label>Environment<select value={settings.environment} onChange={e=>setSettings({...settings,environment:e.target.value})}><option>development</option><option>preview</option><option>production</option></select></label><label>Allowed origins<textarea value={settings.allowedOrigins} onChange={e=>setSettings({...settings,allowedOrigins:e.target.value})} placeholder="https://app.example.com"/></label><label>Usage limit<input type="number" min="0" value={settings.usageLimit} onChange={e=>setSettings({...settings,usageLimit:Number(e.target.value)})}/></label><Button primary type="submit" disabled={loading}>{loading&&<Loader2 className="spin" size={14}/>}Save project settings</Button></form>:<><small className="eyebrow">Project-scoped model access</small><h3>AI Providers</h3><p className="settings-copy">Configure a provider for this project. API keys are never shown after saving.</p><div className="provider-tabs">{Object.keys(defaults).map(p=><button className={provider===p?'active':''} key={p} onClick={()=>setProvider(p)}>{providerLabels[p]||p}</button>)}</div><div className="provider-status">{configured?<><CheckCircle2 size={14}/> Key configured · masked</>:<><AlertTriangle size={14}/> Not configured</>}</div><label>Provider<input value={provider} readOnly/></label><label>Base URL<input value={form.baseUrl} onChange={e=>setForm({...form,baseUrl:e.target.value})}/></label><label>Model<select value={form.model} onChange={e=>setForm({...form,model:e.target.value})}>{provider==='openrouter'&&freeModels.length?freeModels.map((m:any)=><option value={m.id} key={m.id}>{m.name||m.id} · free</option>):providerModels[provider].map((m:any)=><option value={m[0]} key={m[0]}>{m[1]}</option>)}{form.model&&!((provider==='openrouter'&&freeModels.some((m:any)=>m.id===form.model))||providerModels[provider].some((m:any)=>m[0]===form.model))&&<option value={form.model}>{form.model} · current</option>}</select><small className="field-help">{provider==='openrouter'?'Use the button below to load every free model available to this key.':'Choose the model used for AI generation in this project.'}</small></label>{provider==='openrouter'&&<Button disabled={!configured||modelsLoading} onClick={loadFreeModels}>{modelsLoading&&<Loader2 className="spin" size={14}/>} {modelsLoading?'Loading free models…':'Load all free models'}</Button>}<label>API key<input type="password" value={form.key||''} onChange={e=>setForm({...form,key:e.target.value})} placeholder={configured?'Enter a new key to rotate it':'Paste your API key'}/></label><div className="provider-actions"><Button primary disabled={loading||!form.key} onClick={saveProvider}>{loading&&<Loader2 className="spin" size={14}/>}Save</Button><Button disabled={loading} onClick={testProvider}><RefreshCw size={13}/> Test connection</Button>{configured&&<Button disabled={loading} onClick={removeProvider}><Trash2 size={13}/> Remove</Button>}</div></>}</section></div>}</main></>}
function Settings({project,projects,onSelect,onDeleteProject}:any){
  const [tab,setTab]=useState<'project'|'providers'>('project');
  const [advanced,setAdvanced]=useState(false);
  const [settings,setSettings]=useState<any>({name:'',environment:'development',allowedOrigins:'',usageLimit:100000,lifecycleStatus:'active'});
  const [provider,setProvider]=useState('gemini'); const [form,setForm]=useState<any>(defaults.gemini); const [configured,setConfigured]=useState(false);
  const [message,setMessage]=useState<any>(); const [loading,setLoading]=useState(false); const [loadingSettings,setLoadingSettings]=useState(false); const [loadingProvider,setLoadingProvider]=useState(false); const [modelsLoading,setModelsLoading]=useState(false); const [freeModels,setFreeModels]=useState<any[]>([]);
  useEffect(()=>{if(!project)return;let alive=true;setLoadingSettings(true);setMessage(undefined);request(`/projects/${project.id}/settings`).then(x=>alive&&setSettings({...x,allowedOrigins:(x.allowedOrigins||[]).join('\n')})).catch(e=>alive&&setMessage({error:`Could not load project settings. ${e.message}`})).finally(()=>alive&&setLoadingSettings(false));return()=>{alive=false}},[project?.id]);
  useEffect(()=>{if(!project)return;let alive=true;setLoadingProvider(true);request(`/projects/${project.id}/providers`).then(x=>{if(!alive)return;const c=x.providers?.find((p:any)=>p.provider===provider);setForm(c?{baseUrl:c.baseUrl,model:c.model,key:''}:defaults[provider]);setConfigured(!!c?.configured)}).catch(e=>alive&&setMessage({error:`Could not load provider settings. ${e.message}`})).finally(()=>alive&&setLoadingProvider(false));return()=>{alive=false}},[project?.id,provider]);
  async function saveSettings(e:any){e.preventDefault();if(!project)return;setLoading(true);setMessage(undefined);try{await request(`/projects/${project.id}/settings`,{method:'PATCH',body:JSON.stringify({...settings,allowedOrigins:String(settings.allowedOrigins||'').split('\n').map((x:string)=>x.trim()).filter(Boolean)})});setMessage({success:'Project settings saved.'})}catch(e:any){setMessage({error:`Could not save project settings. ${e.message}`})}finally{setLoading(false)}}
  async function saveProvider(){if(!project)return;setLoading(true);setMessage(undefined);try{await request(`/projects/${project.id}/providers/${provider}`,{method:'PATCH',body:JSON.stringify(form)});setConfigured(true);setForm((x:any)=>({...x,key:''}));setMessage({success:`${provider} configuration saved.`})}catch(e:any){setMessage({error:`Could not save ${provider} settings. ${e.message}`})}finally{setLoading(false)}}
  async function testProvider(){if(!project)return;setLoading(true);setMessage(undefined);try{const result=await request(`/projects/${project.id}/providers/${provider}/test`,{method:'POST',body:JSON.stringify(form)});setMessage(result.reachable?{success:`${provider} · ${form.model} responded successfully.`}:{error:`Test connection failed for ${provider} · ${form.model}. ${result.message||'Check the API key, model, and network connection.'}`})}catch(e:any){setMessage({error:`Could not test ${provider}. ${e.message}`})}finally{setLoading(false)}}
  async function loadFreeModels(){if(!project||provider!=='openrouter')return;setModelsLoading(true);setMessage(undefined);try{const result=await request(`/projects/${project.id}/providers/openrouter/models`);setFreeModels(result.models||[]);setMessage({success:`Loaded ${result.models?.length||0} free OpenRouter models.`})}catch(e:any){setMessage({error:`Could not load OpenRouter models. ${e.message}`})}finally{setModelsLoading(false)}}
  async function removeProvider(){if(!project||!window.confirm(`Remove the ${provider} provider configuration? Its stored key will no longer be used.`))return;setLoading(true);setMessage(undefined);try{await request(`/projects/${project.id}/providers/${provider}`,{method:'DELETE'});setConfigured(false);setForm(defaults[provider]);setMessage({success:`${provider} provider removed.`})}catch(e:any){setMessage({error:`Could not remove ${provider}. ${e.message}`})}finally{setLoading(false)}}
  async function deleteProject(){if(!project||!onDeleteProject||!window.confirm(`Delete "${project.name}" permanently? This will remove the project's data, settings, providers, versions, deployments, and generated files. This action cannot be undone.`))return;setLoading(true);setMessage(undefined);try{await onDeleteProject(project.id)}catch(e:any){setMessage({error:`Could not delete project. ${e.message}`});setLoading(false)}}
  return <><Header eyebrow="Account / Settings" title="Settings"/><main><ProjectBar projects={projects} selectedId={project?.id||''} onSelect={onSelect}/>{!project?<div className="panel empty tall"><SettingsIcon size={28}/><b>Select a project to manage settings</b></div>:<div className="settings"><nav><button className={tab==='project'?'active':''} onClick={()=>setTab('project')}><SettingsIcon size={14}/> Project settings</button><button className={tab==='providers'?'active':''} onClick={()=>setTab('providers')}><Sparkles size={14}/> AI Providers</button><button onClick={()=>window.dispatchEvent(new CustomEvent('appweave:navigate',{detail:'MCP Connections'}))}><Plug size={14}/> MCP Connections</button></nav><section className="panel">{message?.error&&<Notice error>{message.error}</Notice>}{message?.success&&<Notice success>{message.success}</Notice>}{tab==='project'?(loadingSettings?<div className="empty short"><Loader2 className="spin" size={22}/><p>Loading project settings…</p></div>:<><form onSubmit={saveSettings}><small className="eyebrow">Project configuration</small><h3>Environment and access</h3><p className="settings-copy">Keep the essentials here; advanced access controls are optional.</p><label>Project name<input required value={settings.name} onChange={e=>setSettings({...settings,name:e.target.value})}/></label><label>Environment<select value={settings.environment||'development'} onChange={e=>setSettings({...settings,environment:e.target.value})}><option>development</option><option>preview</option><option>production</option></select></label><details className="advanced-settings" open={advanced} onToggle={e=>setAdvanced((e.target as HTMLDetailsElement).open)}><summary>Advanced project settings <small>Origins, limits, and lifecycle</small></summary><label>Allowed origins<textarea value={settings.allowedOrigins||''} onChange={e=>setSettings({...settings,allowedOrigins:e.target.value})} placeholder="https://app.example.com"/></label><label>Usage limit<input type="number" min="0" value={settings.usageLimit??100000} onChange={e=>setSettings({...settings,usageLimit:Number(e.target.value)})}/></label><label>Lifecycle status<select value={settings.lifecycleStatus||'active'} onChange={e=>setSettings({...settings,lifecycleStatus:e.target.value})}><option>active</option><option>paused</option></select></label></details><Button primary type="submit" disabled={loading}>{loading&&<Loader2 className="spin" size={14}/>} {loading?'Saving…':'Save project settings'}</Button></form><div className="danger-zone"><small className="eyebrow">Danger zone</small><h3>Delete project</h3><p className="settings-copy">Permanently remove this project, its data, settings, providers, versions, deployments, and generated files.</p><Button disabled={loading} onClick={deleteProject}><Trash2 size={13}/> Delete project</Button></div></>):<>{loadingProvider?<div className="empty short"><Loader2 className="spin" size={22}/><p>Loading provider settings…</p></div>:<><small className="eyebrow">Project-scoped model access</small><h3>AI Providers</h3><p className="settings-copy">Configure a provider for this project. API keys are never shown after saving.</p><div className="provider-tabs">{Object.keys(defaults).map(p=><button type="button" className={provider===p?'active':''} key={p} onClick={()=>setProvider(p)}>{providerLabels[p]||p}</button>)}</div><div className="provider-status">{configured?<><CheckCircle2 size={14}/> Key configured · masked</>:<><AlertTriangle size={14}/> Not configured</>}</div><label>Provider<input value={provider} readOnly/></label><details className="advanced-settings" open={advanced} onToggle={e=>setAdvanced((e.target as HTMLDetailsElement).open)}><summary>Advanced provider settings <small>Endpoint and model selection</small></summary><label>Base URL<input value={form.baseUrl||''} onChange={e=>setForm({...form,baseUrl:e.target.value})}/></label><label>Model<select value={form.model||''} onChange={e=>setForm({...form,model:e.target.value})}>{provider==='openrouter'&&freeModels.length?freeModels.map((m:any)=><option value={m.id} key={m.id}>{m.name||m.id} · free</option>):providerModels[provider].map((m:any)=><option value={m[0]} key={m[0]}>{m[1]}</option>)}{form.model&&!providerModels[provider].some((m:any)=>m[0]===form.model)&&<option value={form.model}>{form.model} · current</option>}</select><small className="field-help">Choose the model used for provider requests.</small></label>{provider==='openrouter'&&<Button disabled={!configured||modelsLoading} onClick={loadFreeModels}>{modelsLoading&&<Loader2 className="spin" size={14}/>} {modelsLoading?'Loading free models…':'Load all free models'}</Button>}</details><label>API key<input type="password" value={form.key||''} onChange={e=>setForm({...form,key:e.target.value})} placeholder={configured?'Enter a new key to rotate it':'Paste your API key'}/></label><div className="provider-actions"><Button primary disabled={loading||!form.key} onClick={saveProvider}>{loading&&<Loader2 className="spin" size={14}/>} {loading?'Saving…':'Save'}</Button><Button disabled={loading} onClick={testProvider}>{loading&&<Loader2 className="spin" size={14}/>}<RefreshCw size={13}/> Test connection</Button>{configured&&<Button disabled={loading} onClick={removeProvider}><Trash2 size={13}/> Remove</Button>}</div></>}</>}</section></div>}</main></>}

function Auth({onAuth}:any){const [register,setRegister]=useState(false);const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState<any>();async function submit(e:any){e.preventDefault();setError(undefined);try{const b=await request(`/auth/${register?'register':'login'}`,{method:'POST',body:JSON.stringify({email,password})});onAuth(b.user)}catch(e:any){setError(e)}}return <div className="auth"><div className="brand"><Zap size={17}/> app<span>weave</span></div><form className="authbox" onSubmit={submit}><div className="authicon"><Zap size={20}/></div><h1>{register?'Create your workspace':'Welcome back'}</h1><p>{register?'Start building with AppWeave.':'Sign in to your developer workspace.'}</p>{error&&<Notice error>{error.message}{error.requestId&&<small>Request ID: {error.requestId}</small>}</Notice>}<label>Email address<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@company.com"/></label><label>Password<input required minLength={8} type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters"/></label><Button primary type="submit">{register?'Create account':'Sign in'}</Button><div className="switch">{register?'Already have an account?':'New to AppWeave?'} <button type="button" onClick={()=>setRegister(!register)}>{register?'Sign in':'Create an account'}</button></div></form><small className="foot">Private backend engine · public client configuration only</small></div>}
export default function App(){const [user,setUser]=useState<any>(null);const [sessionLoading,setSessionLoading]=useState(true);const [page,setPage]=useState<Page>('Overview');const [open,setOpen]=useState(false);const [projects,setProjects]=useState<Project[]>([]);const [selectedId,setSelectedId]=useState(()=>localStorage.getItem('appweave_project')||'');const [preferencesReady,setPreferencesReady]=useState(false);const selected=useMemo(()=>projects.find(p=>p.id===selectedId),[projects,selectedId]);useEffect(()=>{const navigate=(event:Event)=>setPage((event as CustomEvent<Page>).detail);window.addEventListener('appweave:navigate',navigate);return()=>window.removeEventListener('appweave:navigate',navigate)},[]);
  useEffect(()=>{let alive=true;request('/auth/me').then(x=>{if(alive)setUser(x.user)}).catch(()=>{if(alive)setUser(null)}).finally(()=>alive&&setSessionLoading(false));return()=>{alive=false}},[]);
  const reload=()=>request('/projects').then(async x=>{setProjects(x.projects);try{const pref=await request('/me/preferences');const preferred=pref.preferences?.selectedProjectId;if(preferred&&x.projects.some((p:Project)=>p.id===preferred))setSelectedId(preferred);else if(!selectedId&&x.projects[0])setSelectedId(x.projects[0].id)}catch{if(!selectedId&&x.projects[0])setSelectedId(x.projects[0].id)}finally{setPreferencesReady(true)}}).catch(()=>setPreferencesReady(true));
  useEffect(()=>{if(user)reload()},[user]);
  useEffect(()=>{if(selectedId){localStorage.setItem('appweave_project',selectedId);if(user&&preferencesReady)request('/me/preferences',{method:'PATCH',body:JSON.stringify({selectedProjectId:selectedId})}).catch(()=>{})}else localStorage.removeItem('appweave_project')},[selectedId,user]);
  if(sessionLoading)return <div className="session-loading"><Loader2 className="spin" size={22}/><span>Restoring your session…</span></div>;if(!user)return <Auth onAuth={setUser}/>;const onSelect=(id:string)=>setSelectedId(id);const deleteProject=async(projectId:string)=>{await request(`/projects/${projectId}`,{method:'DELETE'});setSelectedId('');localStorage.removeItem('appweave_project');await reload();setPage('Projects')};const logout=async()=>{try{await request('/auth/logout',{method:'POST'})}finally{setUser(null);setProjects([]);setSelectedId('')}};const go=(p:Page)=>{setPage(p);setOpen(false)};const view=page==='Overview'?<Overview go={go} project={{projects,selectedId,onSelect}}/>:page==='Projects'?<Projects go={go} projects={projects} selectedId={selectedId} onSelect={onSelect} reload={reload}/>:page==='Workspace'?<Workspace project={selected} projects={projects} onSelect={onSelect}/>:page==='Database'?<DatabasePage project={selected} projects={projects} onSelect={onSelect}/>:page==='Versions'?<Ship versions project={selected} projects={projects} onSelect={onSelect}/>:page==='Deployments'?<Ship project={selected} projects={projects} onSelect={onSelect}/>:page==='Settings'?<Settings project={selected} projects={projects} onSelect={onSelect} onDeleteProject={deleteProject}/>:page==='MCP Connections'?<Connections/>:page==='API explorer'?<SimplePage title="API explorer" eyebrow="Build / API explorer" icon={Braces} description="Select a project to inspect its approved API surface and request shapes."/>:<SimplePage title="Logs & monitoring" eyebrow="Observe / Logs" icon={Terminal} description="Select a project to review authenticated requests, builds, and audit activity."/>;return <div className="app"><aside className={open?'sidebar open':'sidebar'}><div className="brand"><Zap size={17}/> app<span>weave</span></div><div className="workspace"><b>AW</b><span><strong>AppWeave</strong><small>{user.email}</small></span></div><ApiStatus/><div className="nav-project"><label htmlFor="nav-project">Selected project</label><select id="nav-project" value={selectedId} onChange={e=>onSelect(e.target.value)}><option value="">Select a project</option>{projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></div><nav className="primary-nav">{navigationGroups.map(group=><div className="nav-group" key={group.label}><small>{group.label}</small>{group.items.map(item=>{const Icon=pageIcons[item];return <button key={item} className={page===item?'selected':''} onClick={()=>go(item)}><Icon size={15}/>{item}</button>})}</div>)}</nav><div className="bottom"><div className="user"><b>{user.email.slice(0,2).toUpperCase()}</b><span><strong>{user.email}</strong><small>Authenticated workspace</small></span><button onClick={logout} title="Sign out"><LogOut size={15}/></button></div></div></aside><div className="main"><div className="mobile"><button onClick={()=>setOpen(!open)}><Menu/></button><b>app<span>weave</span></b></div><ErrorBoundary>{view}</ErrorBoundary></div></div>}
